/**
 * Identifies one intended trade. A restart, a double-click, or two overlapping
 * ticks all regenerate the same key, and the engine refuses to submit a key it
 * has already used — which is what stops one signal becoming two positions.
 * The time bucket lets a genuinely new setup on the same symbol through later.
 */
export function executionKey({ accountId, symbol, direction, at, bucketMs = 60_000 }) {
  return `${accountId}:${symbol}:${direction}:${Math.floor(at / bucketMs)}`
}

const key = executionKey({ accountId, symbol, direction: decision.action, at: now() })
if (usedKeys.has(key)) {
  record({ kind: 'duplicate-suppressed', symbol, key })
  continue
}

setState(BOT_STATES.ORDER_APPROVED, symbol)
// Reserved before the await, not after: an exception mid-flight must
// not free the key, because the order may already be live.
usedKeys.add(key)

/* The trade must be able to pay for itself.
   A round trip costs two fills. If the whole distance to target is worth
   less than a small multiple of that cost, the trade is a fee transfer with
   a lottery ticket attached — it can only be profitable if it also gets
   lucky on slippage. This is the check that a 31-winners-and-still-down
   result is asking for: the losses were never directional, they were
   frictional. */
if (config.feeBps != null && config.minRewardToCost != null && target != null) {
  /* Slippage is part of the cost, not a rounding error.
     This check used to count fees only. A fill that arrives a few basis
     points adverse costs real money on both legs, and leaving it out
     understated the true round trip by about a third — so trades that were
     actually below cost were passing a gate whose whole job is to catch
     them. On a short horizon, where cost is the binding constraint rather
     than direction, that gap IS the 31-winners-and-still-down result. */
  const costBps = (config.feeBps + (config.slippageBps ?? 0)) * 2
  const roundTripCost = notional * (costBps / 10_000)
  const rewardAtTarget = Math.abs(target - entry) * decision.quantity
  if (rewardAtTarget < roundTripCost * config.minRewardToCost) {
    return fail(
      'EDGE_BELOW_COST',
      `Target is worth ${rewardAtTarget.toFixed(2)} against ${roundTripCost.toFixed(2)} in fees and slippage (need ${config.minRewardToCost}×).`,
    )
  }
}

/**
 * Encrypt a secret into a self-describing envelope.
 *
 * `aad` binds the ciphertext to the row it belongs to — pass something stable
 * and unique like `${userId}:${accountId}`. Without it, an attacker with write
 * access to the store could move another user's encrypted credential into their
 * own row and trade with it, and the decryption would succeed because the
 * bytes are perfectly valid. With it, that swap fails authentication.
 */
export function encryptSecret(plaintext, { aad, env = process.env } = {}) {
  if (typeof plaintext !== 'string' || plaintext.length === 0) {
    throw new Error('Nothing to encrypt.')
  }
  if (!aad) throw new Error('An aad binding (e.g. "userId:accountId") is required.')

  const key = loadKey(env)
  const iv = crypto.randomBytes(IV_BYTES)
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv)
  cipher.setAAD(Buffer.from(aad, 'utf8'))

  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()])
  const tag = cipher.getAuthTag()

  return [VERSION, iv.toString('base64'), tag.toString('base64'), ciphertext.toString('base64')].join('.')
}

// Throws on a wrong key, a wrong aad, or any tampering. Deliberately not
// caught here: a failure to authenticate must reach the caller, never be
// downgraded into an empty string that then gets used as a secret.
return Buffer.concat([decipher.update(Buffer.from(dataB64, 'base64')), decipher.final()]).toString('utf8')

const EMBEDDED = /((?:api[_-]?key|api[_-]?secret|secret|signature|authorization|token|password)\s*[:=]\s*)(\S+)/gi

function scrubText(value) {
  return value.replace(EMBEDDED, (_m, label) => `${label}[redacted]`)
}

function looksSecret(value) {
  if (value.length < 20) return false
  if (IDENTIFIER.test(value)) return false
  if (!/^[A-Za-z0-9_\-+/=]+$/.test(value)) return false
  const mixedCase = /[a-z]/.test(value) && /[A-Z]/.test(value)
  const alphanumeric = /[a-zA-Z]/.test(value) && /[0-9]/.test(value)
  return mixedCase || alphanumeric
}

/**
 * Returns null for a forbidden pairing, otherwise a preference score that
 * may legitimately be negative.
 *
 * Null and "low score" have to stay distinct. The anti-rematch penalty below
 * is a preference, not a rule: when two people are the only ones waiting,
 * pairing them again is far better than leaving them both in the queue
 * forever, which is what treating any negative score as forbidden used to do.
 */
score(a, b) {
  if (a.mode !== b.mode) return null;
  if (a.clientId === b.clientId) return null;
  if (a.blocked.has(b.clientId) || b.blocked.has(a.clientId)) return null;
  if (!this.countryAllows(a, b) || !this.countryAllows(b, a)) return null;
  if (!this.genderAllows(a, b) || !this.genderAllows(b, a)) return null;

  let score = 0;

  const shared = a.interests.filter((tag) => b.interests.includes(tag));
  score += shared.length * 40;

  // Matching moods: people wanting the same energy pair faster.
  if (a.mood && b.mood && a.mood === b.mood) score += 30;

  // Both sides filtered on country and both are satisfied — reward it.
  if (a.countries.length && b.countries.length) score += 10;

  const waited = Date.now() - Math.min(a.joinedAt, b.joinedAt);
  score += Math.min(Math.floor(waited / 1000), 60);

  // Gently avoid rematching the last few people this client spoke to.
  const seen = this.recent.get(a.clientId) || [];
  if (seen.includes(b.clientId)) score -= 200;

  return score;
}

/**
 * Re-attempt matching for everyone already waiting.
 *
 * Matching otherwise only runs when someone joins the queue, so two people
 * whose filters relax past each other would both sit there indefinitely with
 * nobody to trigger a retry. The server runs this on a timer.
 */
sweep() {
  const pairs = [];
  for (const peer of [...this.pool.values()]) {
    if (!this.pool.has(peer.id)) continue; // already paired earlier in this sweep
    const partner = this.findPartner(peer);
    if (!partner) continue;
    this.pool.delete(peer.id);
    this.pool.delete(partner.id);
    this.rememberPair(peer, partner);
    pairs.push([peer, partner]);
  }
  return pairs;
}
